<template><div class="page"><el-card><template #header><div style="display:flex;justify-content:space-between"><span>用户积分</span><el-button type="primary" size="small" @click="showDialog=true">调整积分</el-button></div></template><el-table :data="list" border><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="user_id" label="用户ID" width="100"/><el-table-column prop="nickname" label="用户"/><el-table-column prop="points" label="积分" width="100"/><el-table-column prop="type" label="类型" width="120"/><el-table-column prop="description" label="说明"/><el-table-column prop="created_at" label="时间" width="170"/></el-table></el-card><el-dialog v-model="showDialog" title="调整积分" width="500px"><el-form :model="form" label-width="80px"><el-form-item label="用户ID"><el-input-number v-model="form.user_id" :min="1"/></el-form-item><el-form-item label="积分"><el-input-number v-model="form.points" :min="0"/></el-form-item><el-form-item label="类型"><el-input v-model="form.type" placeholder="如：充值/消费/活动"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea" :rows="2"/></el-form-item></el-form><template #footer><el-button @click="showDialog=false">取消</el-button><el-button type="primary" @click="submit">确定</el-button></template></el-dialog></div></template><script setup>import{ref,reactive,onMounted}from'vue';import{ElMessage}from'element-plus';import request from'@/utils/request';const list=ref([]);const showDialog=ref(false);const form=reactive({user_id:1,points:0,type:'',description:''});const loadList=async()=>{const res=await request({url:'/user-points'});list.value=res.data?.list||[]};const submit=async()=>{await request({url:'/user-points',method:'post',data:form});ElMessage.success('调整成功');showDialog.value=false;loadList()};onMounted(()=>loadList())</script>
